// Group is one admin-composed named scope (accounts design.md §1) as the
// domain sees it: a named set of member Collections and member users. Doc is
// the opaque schema-versioned operator document (doc_json + schema_version):
// identity stores and returns it verbatim, parsing nothing (the User Prefs
// discipline) — SetGroupDoc replaces it whole, never merging, so an operator
// edit can't be silently folded into a stale read. The document's one
// current vocabulary is per-source read-time mutes (design.md D8), shaped
// like the metadata_source_prefs gates: a JSON object whose "mutes" key maps
// a plugin id to true (muted); an absent plugin id means not muted. New knob
// shapes ride the same document under new keys and read as absent on
// documents written before they existed — migrations NEVER rewrite an
// operator-authored document, they only raise what fresh documents default
// to.
type Group struct {
	ID            int64
	Name          string
	Doc           string
	SchemaVersion int
	CreatedAt     time.Time
	UpdatedAt     time.Time
}

// CollectionOrder is one library's RESOLVED display position for one user
// (task 3.2): across every group the user belongs to that carries the
// library, the row with the MIN position wins, ties broken by the LOWER
// group id (GroupID records the winner — the provenance the overlap tests
// pin). The slice CollectionOrder returns is ordered by (Position,
// LibraryID) — the display order. Resolution reads memberships only: a
// library id whose library row is gone rides through here and is dropped by
// the LIVE intersection at viewer resolution (task 3.4; design.md D5 —
// orphaned grant rows are harmless and invisible).
type CollectionOrder struct {
	LibraryID int64
	Position  int64
	GroupID   int64
}

// GroupCollection is one member-Collections row of ONE group (task 9.2's
// reader shape): a library id and its display position — the stored pair,
// not CollectionOrder's per-user resolution across groups.
type GroupCollection struct {
	LibraryID int64
	Position  int64
}

// normalizeGroupName is the group-name discipline: trim surrounding spaces
// and reject the empty remainder. Case is PRESERVED — groups are
// operator-composed display names, not login identifiers (the users-table
// lowercase rule exists for credential matching, which groups never do); the
// UNIQUE constraint is therefore exact-match. Decided and documented here
// (task 3.2) — every entry point normalizes before it queries or inserts.
func normalizeGroupName(name string) (string, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return "", fmt.Errorf("identity: empty group name")
	}
	return name, nil
}

const groupColumns = `id, name, doc_json, schema_version, created_at, updated_at`

// groupFromRow assembles a Group from scanned row values (column order per
// groupColumns): the TEXT stamps to time.
func groupFromRow(id int64, name, doc string, schemaVersion int, createdAt, updatedAt string) (Group, error) {
	created, err := time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return Group{}, fmt.Errorf("identity: group created_at %q: %w", createdAt, err)
	}
	updated, err := time.Parse(time.RFC3339Nano, updatedAt)
	if err != nil {
		return Group{}, fmt.Errorf("identity: group updated_at %q: %w", updatedAt, err)
	}
	return Group{
		ID:            id,
		Name:          name,
		Doc:           doc,
		SchemaVersion: schemaVersion,
		CreatedAt:     created,
		UpdatedAt:     updated,
	}, nil
}

// scanGroupRow scans one groups row in groupColumns order into a Group —
// the read half shared by getGroup and GroupByID.
func scanGroupRow(row *sql.Row) (Group, error) {
	var (
		g         Group
		schemaVer int
		createdAt string
		updatedAt string
	)
	if err := row.Scan(&g.ID, &g.Name, &g.Doc, &schemaVer, &createdAt, &updatedAt); err != nil {
		return Group{}, err
	}
	return groupFromRow(g.ID, g.Name, g.Doc, schemaVer, createdAt, updatedAt)
}

// groupRowErr maps a groups-row read failure to the handler vocabulary: the
// wrapped sql.ErrNoRows unknown-group convention (handlers map to 404),
// other failures wrapped with the read's name.
func groupRowErr(what string, err error) error {
	if errors.Is(err, sql.ErrNoRows) {
		return fmt.Errorf("%s: unknown group: %w", what, err)
	}
	return fmt.Errorf("%s: %w", what, err)
}

// getGroup reads one group by the query's name parameter. Unknown groups
// surface as wrapped sql.ErrNoRows (the repo convention handlers map to 404).
func (s *Service) getGroup(ctx context.Context, name string) (Group, error) {
	g, err := scanGroupRow(s.st.DB().QueryRowContext(ctx,
		`SELECT `+groupColumns+` FROM groups WHERE name = ?`, name))
	if err != nil {
		return Group{}, groupRowErr("identity: get group", err)
	}
	return g, nil
}

// GroupByID reads one group by row id — the admin groups surface's
// addressing (task 9.2, the UserByID mirror): URLs carry the stable id
// (rename-proof, slash-safe), while the domain's writes stay name-keyed, so
// every mutating caller resolves id → name first. Unknown groups surface as
// wrapped sql.ErrNoRows.
func (s *Service) GroupByID(ctx context.Context, id int64) (Group, error) {
	g, err := scanGroupRow(s.st.DB().QueryRowContext(ctx,
		`SELECT `+groupColumns+` FROM groups WHERE id = ?`, id))
	if err != nil {
		return Group{}, groupRowErr("identity: get group by id", err)
	}
	return g, nil
}

// Groups lists every group, name-ordered — the admin groups surface's list
// reader (task 9.2, the Users mirror). The empty store resolves to an empty
// (non-nil) slice.
func (s *Service) Groups(ctx context.Context) ([]Group, error) {
	rows, err := s.st.DB().QueryContext(ctx,
		`SELECT `+groupColumns+` FROM groups ORDER BY name`)
	if err != nil {
		return nil, fmt.Errorf("identity: list groups: %w", err)
	}
	defer func() { _ = rows.Close() }()
	out := []Group{}
	for rows.Next() {
		var (
			id        int64
			name, doc string
			schemaVer int
			createdAt string
			updatedAt string
		)
		if err := rows.Scan(&id, &name, &doc, &schemaVer, &createdAt, &updatedAt); err != nil {
			return nil, fmt.Errorf("identity: scan group: %w", err)
		}
		g, err := groupFromRow(id, name, doc, schemaVer, createdAt, updatedAt)
		if err != nil {
			return nil, fmt.Errorf("identity: list groups: %w", err)
		}
		out = append(out, g)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("identity: list groups: %w", err)
	}
	return out, nil
}

// GroupMembers lists a group's member users, username-ordered — the
// member-users axis reader the admin surface serves (task 9.2). Unknown
// groups surface as wrapped sql.ErrNoRows. Rows ride the full User struct
// (hashes included, the users-table contract); the api layer never serves
// them (the 9.1 discipline point).
func (s *Service) GroupMembers(ctx context.Context, group string) ([]User, error) {
	group, err := normalizeGroupName(group)
	if err != nil {
		return nil, err
	}
	gid, err := s.groupID(ctx, group)
	if err != nil {
		return nil, err
	}
	rows, err := s.st.DB().QueryContext(ctx, `
SELECT u.id, u.username, u.display_name, u.password_hash, u.role, u.prefs_json, u.disabled, u.created_at, u.updated_at
FROM group_members gm
JOIN users u ON u.id = gm.user_id
WHERE gm.group_id = ?
ORDER BY u.username`, gid)
	if err != nil {
		return nil, fmt.Errorf("identity: group members %q: %w", group, err)
	}
	defer func() { _ = rows.Close() }()
	out := []User{}
	for rows.Next() {
		var (
			id                                               int64
			username, displayName, passwordHash, role, prefs string
			disabled                                         int
			createdAt, updatedAt                             string
		)
		if err := rows.Scan(&id, &username, &displayName, &passwordHash, &role,
			&prefs, &disabled, &createdAt, &updatedAt); err != nil {
			return nil, fmt.Errorf("identity: scan group member: %w", err)
		}
		u, err := userFromRow(id, username, displayName, passwordHash, role, prefs, disabled, createdAt, updatedAt)
		if err != nil {
			return nil, fmt.Errorf("identity: group members %q: %w", group, err)
		}
		out = append(out, u)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("identity: group members %q: %w", group, err)
	}
	return out, nil
}

// GroupCollections lists a group's member Collections with their display
// positions, (position, library_id)-ordered — the member-Collections axis
// reader the admin surface serves (task 9.2). Membership-only by contract:
// an orphaned library row rides through (the LIVE intersection with the
// libraries table drops it at viewer resolution — task 3.4, design.md D5).
// Unknown groups surface as wrapped sql.ErrNoRows.
func (s *Service) GroupCollections(ctx context.Context, group string) ([]GroupCollection, error) {
	group, err := normalizeGroupName(group)
	if err != nil {
		return nil, err
	}
	gid, err := s.groupID(ctx, group)
	if err != nil {
		return nil, err
	}
	rows, err := s.st.DB().QueryContext(ctx, `
SELECT gc.library_id, gc.position
FROM group_collections gc
WHERE gc.group_id = ?
ORDER BY gc.position, gc.library_id`, gid)
	if err != nil {
		return nil, fmt.Errorf("identity: group collections %q: %w", group, err)
	}
	defer func() { _ = rows.Close() }()
	out := []GroupCollection{}
	for rows.Next() {
		var gc GroupCollection
		if err := rows.Scan(&gc.LibraryID, &gc.Position); err != nil {
			return nil, fmt.Errorf("identity: scan group collection: %w", err)
		}
		out = append(out, gc)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("identity: group collections %q: %w", group, err)
	}
	return out, nil
}

// groupID resolves a group name to its row id (the membership tables key by
// id); unknown groups surface as wrapped sql.ErrNoRows.
func (s *Service) groupID(ctx context.Context, name string) (int64, error) {
	var id int64
	err := s.st.DB().QueryRowContext(ctx,
		`SELECT id FROM groups WHERE name = ?`, name).Scan(&id)
	if errors.Is(err, sql.ErrNoRows) {
		return 0, fmt.Errorf("identity: unknown group: %w", err)
	}
	if err != nil {
		return 0, fmt.Errorf("identity: resolve group %q: %w", name, err)
	}
	return id, nil
}

// userID resolves a normalized username to its row id (group_members keys by
// id); unknown users surface as wrapped sql.ErrNoRows.
func (s *Service) userID(ctx context.Context, name string) (int64, error) {
	var id int64
	err := s.st.DB().QueryRowContext(ctx,
		`SELECT id FROM users WHERE username = ?`, name).Scan(&id)
	if errors.Is(err, sql.ErrNoRows) {
		return 0, fmt.Errorf("identity: unknown user: %w", err)
	}
	if err != nil {
		return 0, fmt.Errorf("identity: resolve user %q: %w", name, err)
	}
	return id, nil
}

// CreateGroup inserts one group: the name is trimmed (case preserved — see
// normalizeGroupName; a duplicate violates the UNIQUE constraint and yields
// the wrapped error handlers map to 409) and the row lands with the empty
// doc document at schema version 1 (the column defaults).
func (s *Service) CreateGroup(ctx context.Context, name string) (Group, error) {
	name, err := normalizeGroupName(name)
	if err != nil {
		return Group{}, err
	}
	stamp := formatStamp(s.now())
	res, err := s.st.DB().ExecContext(ctx,
		`INSERT INTO groups (name, created_at, updated_at) VALUES (?, ?, ?)`,
		name, stamp, stamp)
	if err != nil {
		return Group{}, fmt.Errorf("identity: create group %q: %w", name, err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return Group{}, fmt.Errorf("identity: create group last id: %w", err)
	}
	return Group{
		ID:            id,
		Name:          name,
		Doc:           "{}",
		SchemaVersion: 1,
		CreatedAt:     s.now(),
		UpdatedAt:     s.now(),
	}, nil
}

// Get reads one group by name (trimmed before the lookup), including its
// doc document and schema version — the READ half of the schema-versioned
// doc_json contract.
func (s *Service) GetGroup(ctx context.Context, name string) (Group, error) {
	name, err := normalizeGroupName(name)
	if err != nil {
		return Group{}, err
	}
	return s.getGroup(ctx, name)
}

// RenameGroup moves a group to a new name (both trimmed): the id, members,
// and doc document all stay put — name is display metadata, never a foreign
// key (the membership tables key by id). Unknown groups and UNIQUE collisions
// on the new name surface as the wrapped errors handlers map to 404/409.
func (s *Service) RenameGroup(ctx context.Context, name, newName string) error {
	name, err := normalizeGroupName(name)
	if err != nil {
		return err
	}
	newName, err = normalizeGroupName(newName)
	if err != nil {
		return err
	}
	return s.execGroupOne(ctx, "identity: rename group",
		`UPDATE groups SET name = ?, updated_at = ? WHERE name = ?`,
		newName, formatStamp(s.now()), name)
}

// DeleteGroup deletes the group AND its membership rows (group_members,
// group_collections) in one transaction — the tables carry no foreign keys,
// so the cascade is this method's job, never a leftover to sweep. Unknown
// groups surface as wrapped sql.ErrNoRows.
func (s *Service) DeleteGroup(ctx context.Context, name string) error {
	name, err := normalizeGroupName(name)
	if err != nil {
		return err
	}
	tx, err := s.st.DB().BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("identity: delete group tx: %w", err)
	}
	defer func() { _ = tx.Rollback() }()

	gid, err := s.groupID(ctx, name)
	if err != nil {
		return err
	}
	for _, q := range []string{
		`DELETE FROM group_members WHERE group_id = ?`,
		`DELETE FROM group_collections WHERE group_id = ?`,
		`DELETE FROM groups WHERE id = ?`,
	} {
		if _, err := tx.ExecContext(ctx, q, gid); err != nil {
			return fmt.Errorf("identity: delete group %q: %w", name, err)
		}
	}
	return tx.Commit()
}

// AddUser adds a user to a group's member-users axis. Idempotent by
// decision (task 3.2): re-adding an existing member is a no-op (INSERT OR
// IGNORE — the composite PK already holds the pair), never an error.
// Unknown groups and users surface as wrapped sql.ErrNoRows — a membership
// row never lands for a name that doesn't resolve (fail fast; dangling rows
// arise only from later deletes, which is 3.5's cascade seam).
func (s *Service) AddUser(ctx context.Context, group, username string) error {
	group, err := normalizeGroupName(group)
	if err != nil {
		return err
	}
	username, err = normalizeUsername(username)
	if err != nil {
		return err
	}
	gid, err := s.groupID(ctx, group)
	if err != nil {
		return err
	}
	uid, err := s.userID(ctx, username)
	if err != nil {
		return err
	}
	if _, err := s.st.DB().ExecContext(ctx,
		`INSERT OR IGNORE INTO group_members (group_id, user_id) VALUES (?, ?)`,
		gid, uid); err != nil {
		return fmt.Errorf("identity: add user %q to group %q: %w", username, group, err)
	}
	return nil
}

// RemoveUser removes a user from a group's member-users axis. Idempotent by
// decision (task 3.2): removing a non-member is a no-op (DELETE of an absent
// pair), never an error. Unknown groups and users still surface as wrapped
// sql.ErrNoRows — the names must resolve even when the membership doesn't.
func (s *Service) RemoveUser(ctx context.Context, group, username string) error {
	group, err := normalizeGroupName(group)
	if err != nil {
		return err
	}
	username, err = normalizeUsername(username)
	if err != nil {
		return err
	}
	gid, err := s.groupID(ctx, group)
	if err != nil {
		return err
	}
	uid, err := s.userID(ctx, username)
	if err != nil {
		return err
	}
	if _, err := s.st.DB().ExecContext(ctx,
		`DELETE FROM group_members WHERE group_id = ? AND user_id = ?`,
		gid, uid); err != nil {
		return fmt.Errorf("identity: remove user %q from group %q: %w", username, group, err)
	}
	return nil
}

// AddCollection adds a library to a group's member-Collections axis at the
// given display position. Overlap is allowed by design (two groups may carry
// the same library — resolution picks the winner, see CollectionOrder).
// Re-adding a library the group already carries REPLACES its position (the
// upsert is the re-position action — one row per pair, the composite PK).
// The library id is NOT validated against the libraries table (the
// UpsertMetadataSourcePref operator-intent precedent): a pref is intent
// keyed by id, and a row orphaned by a later library delete is harmless and
// invisible at the live intersection (task 3.4, design.md D5). Unknown
// groups surface as wrapped sql.ErrNoRows.
func (s *Service) AddCollection(ctx context.Context, group string, libraryID, position int64) error {
	group, err := normalizeGroupName(group)
	if err != nil {
		return err
	}
	gid, err := s.groupID(ctx, group)
	if err != nil {
		return err
	}
	if _, err := s.st.DB().ExecContext(ctx, `
INSERT INTO group_collections (group_id, library_id, position) VALUES (?, ?, ?)
ON CONFLICT(group_id, library_id) DO UPDATE SET position = excluded.position`,
		gid, libraryID, position); err != nil {
		return fmt.Errorf("identity: add collection %d to group %q: %w", libraryID, group, err)
	}
	return nil
}

// RemoveCollection removes a library from a group's member-Collections axis.
// Idempotent by decision (task 3.2): removing a non-member library is a
// no-op, never an error. Unknown groups surface as wrapped sql.ErrNoRows.
func (s *Service) RemoveCollection(ctx context.Context, group string, libraryID int64) error {
	group, err := normalizeGroupName(group)
	if err != nil {
		return err
	}
	gid, err := s.groupID(ctx, group)
	if err != nil {
		return err
	}
	if _, err := s.st.DB().ExecContext(ctx,
		`DELETE FROM group_collections WHERE group_id = ? AND library_id = ?`,
		gid, libraryID); err != nil {
		return fmt.Errorf("identity: remove collection %d from group %q: %w", libraryID, group, err)
	}
	return nil
}

// SetGroupDoc replaces a group's doc document and schema version WHOLE —
// the WRITE half of the schema-versioned doc_json contract. Identity never
// merges or reshapes the document (opaque passthrough); the caller supplies
// the schema version it authored the document against. Migrations never
// call through here — the no-rewrite rule is a read-side property (new knobs
// read as absent on old documents), never a write-side backfill. Unknown
// groups surface as wrapped sql.ErrNoRows.
func (s *Service) SetGroupDoc(ctx context.Context, name, doc string, schemaVersion int) error {
	name, err := normalizeGroupName(name)
	if err != nil {
		return err
	}
	return s.execGroupOne(ctx, "identity: set group doc",
		`UPDATE groups SET doc_json = ?, schema_version = ?, updated_at = ? WHERE name = ?`,
		doc, schemaVersion, formatStamp(s.now()), name)
}

// CollectionOrder resolves one user's display order across ALL their groups'
// member-Collections: per library the MIN position wins, ties broken by the
// LOWER group id; the slice is ordered by (Position, LibraryID). A user in
// no group, or in groups carrying no collections, resolves to an empty
// (non-nil) slice. Membership-only by contract (task 3.2): the LIVE
// intersection with the libraries table — which drops orphaned grant rows —
// is viewer resolution's job (task 3.4, design.md D5).
func (s *Service) CollectionOrder(ctx context.Context, userID int64) ([]CollectionOrder, error) {
	rows, err := s.st.DB().QueryContext(ctx, `
SELECT gc.library_id, gc.position, gc.group_id
FROM group_collections gc
JOIN group_members gm ON gm.group_id = gc.group_id
WHERE gm.user_id = ?`, userID)
	if err != nil {
		return nil, fmt.Errorf("identity: collection order user %d: %w", userID, err)
	}
	defer rows.Close()

	// Resolve min-position / lower-group-id per library in memory — the
	// store stays value-agnostic (the schema comment's rule); the rule is
	// the caller's, and this is the caller.
	best := make(map[int64]CollectionOrder)
	for rows.Next() {
		var co CollectionOrder
		if err := rows.Scan(&co.LibraryID, &co.Position, &co.GroupID); err != nil {
			return nil, fmt.Errorf("identity: collection order scan: %w", err)
		}
		cur, ok := best[co.LibraryID]
		if !ok || co.Position < cur.Position || (co.Position == cur.Position && co.GroupID < cur.GroupID) {
			best[co.LibraryID] = co
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("identity: collection order user %d: %w", userID, err)
	}

	out := make([]CollectionOrder, 0, len(best))
	for _, co := range best {
		out = append(out, co)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Position != out[j].Position {
			return out[i].Position < out[j].Position
		}
		return out[i].LibraryID < out[j].LibraryID
	})
	return out, nil
}

// UserGroups lists ONE user's groups — the profile's groups facts (task
// 8.1). The group_members ⋈ groups join in ResolveViewer's style: LIVE
// group rows only (a membership whose group row is gone joins to nothing
// and is skipped silently), ordered by name for a deterministic display
// order. A user in no group resolves to an empty (non-nil) slice.
func (s *Service) UserGroups(ctx context.Context, userID int64) ([]Group, error) {
	rows, err := s.st.DB().QueryContext(ctx, `
SELECT g.id, g.name, g.doc_json, g.schema_version, g.created_at, g.updated_at
FROM group_members gm
JOIN groups g ON g.id = gm.group_id
WHERE gm.user_id = ?
ORDER BY g.name`, userID)
	if err != nil {
		return nil, fmt.Errorf("identity: user groups user %d: %w", userID, err)
	}
	defer rows.Close()

	out := make([]Group, 0)
	for rows.Next() {
		var (
			id        int64
			name, doc string
			schemaVer int
			createdAt string
			updatedAt string
		)
		if err := rows.Scan(&id, &name, &doc, &schemaVer, &createdAt, &updatedAt); err != nil {
			return nil, fmt.Errorf("identity: user groups scan user %d: %w", userID, err)
		}
		g, err := groupFromRow(id, name, doc, schemaVer, createdAt, updatedAt)
		if err != nil {
			return nil, fmt.Errorf("identity: user groups user %d: %w", userID, err)
		}
		out = append(out, g)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("identity: user groups user %d: %w", userID, err)
	}
	return out, nil
}

// execGroupOne runs one single-row UPDATE and maps an empty effect to the
// wrapped sql.ErrNoRows unknown-group convention (the execOne mirror for the
// groups domain).
func (s *Service) execGroupOne(ctx context.Context, what, q string, args ...any) error {
	res, err := s.st.DB().ExecContext(ctx, q, args...)
	if err != nil {
		return fmt.Errorf("%s: %w", what, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("%s affected: %w", what, err)
	}
	if n == 0 {
		return fmt.Errorf("%s: unknown group: %w", what, sql.ErrNoRows)
	}
	return nil
}
